  '1aa70929e14d27e365dfc3608e4450e31479f902e831db9a5209ceaf190af455' => '要使用此企业功能，您首先需要像往常一样在 Open-AudIT 中创建用户。 无需指定密码。 您必须分配角色和组织。 Open-AudIT 中的用户名应与 Entra <i>首选用户名</i> 属性匹配。 不需要全名或电子邮件 - 这些将从 Entra 填充。 如果您不知道您的用户<i>首选用户名</i>，请不要担心。 您可以在 Open-AudIT 中创建新的身份验证方法，并在 Entra 中创建企业应用程序，当用户尝试在没有预先存在的用户的情况下登录 Open-AudIT 时，请检查日志，您将看到他们的<i>首选用户名</i>已记录，以方便您使用。',
