  '1ded4550513e19e1c29cad55a3e9450438ba7da27b7d7d5890ddf9a57ca4b7ea' => 'VMware Workstation 倾向于使用非全局唯一的 MAC 地址。 IE - 两个不同的工作站可能正在运行 VMware Workstation，并且有两个具有相同 MAC 地址的不同虚拟机。 这些计算机永远不需要使用此 MAC 地址在其主机外部执行网络连接，但 Open-AudIT 将在审核时发现 MAC 地址。 我们应该根据这些mac地址来确定唯一性吗？ 这些 MAC 地址通常以以下之一开头：00:0c:29、00:50:56、00:05:69、00:1c:14。',
