  '1e4c6c44f3e958b08853abe693e4f7ebb83b0a428417b05dd13cec211491bb8e' => '作为审核的一部分，可执行文件功能会扫描设备的磁盘，并检查程序包管理器是否已知每个可执行文件。 由于它使用包管理器，因此该功能仅适用于 Linux 目标设备，并且仅适用于基于 rpm 或 deb 的发行版。 任何基于 Redhat 或 Debian 的东西都应该可以工作。',
