  '1fae9e04ff602f3a8ffe630ac2a7c05d165a3359792c1ffaa7af1006cfc782a4' => '收集器本质上是 Open-AudIT 在<i>收集器</i>模式下的完整安装。 此模式将减少可见功能，以简化和集中应用程序。 它旨在收集有关本地网络和设备的信息，其中防火墙和/或网络穿越是服务器的问题。',
