  '2a3cca15facb00b1788a94753dfaf665aa7420b52299f9e0f5ed115029a8a0fa' => '故障排除后应将其注释掉，因为调试模式会在磁盘上生成大量日志，但没有任何好处。',
  '2a8adc842be4c52eb2a8e45b035b7df694ed974b907ad00d7d2d975a417706bd' => '指定的用户存在于 LDAP 中，但 Open-AudIT 未配置为使用角色的 LDAP 组，并且 Open-AudIT 中不存在该用户。 在 Open-AudIT LDAP 服务器屏幕上选择<i>对角色使用 LDAP</i>，或者在 Open-AudIT 中创建此用户并分配角色和组织。',
