  '2b0cd6b55267c25eca2db35db51194c4eacb57d83c728dcab872d7e9a9e02a66' => '从内部创建外部',
  '2b0dcdd40016096b852d9d5b79de2ad570249dc8e4d4ebe4fa4ab81e2aa9af35' => '行动',
  '2b09e8f93b369ddae8c8d5e7de17414920279d8cfbc77e04e16f8a86b44c1e61' => '创建集成后，当您查看集成的详细信息时，您会注意到一个名为“调试”的字段。 默认情况下此设置为“否”。 将其更改为 yes 可在执行集成时提供额外的日志记录。 调试不应保留为“是”。 这是因为调试输出将包含从外部系统检索到的所有内容 - 包括 WMI 和 SNMP 凭据等项目。 仅当发生问题并且您希望更深入地了解是否可以确定原因时，才应使用调试选项。',
  '2b3eaec21e74f49a2d318767276b70ce252713380fdae863b98fa7bff128d87d' => '确认者',
