  '4b8bdb9a894c28fbe717f4eb0dab8595feb14909fb4288d5dd7f4b9ea1b2d017' => '每次发现设备或处理审核结果时，都会从数据库中检索所有规则并根据特定设备的属性运行。 规则一次针对一台设备运行 - 没有工具可以说<i>针对所有设备运行规则<i>或<i>针对这些设备运行规则<i>。 单个规则将测试设备的一个或多个属性，如果它们与规则匹配，则将应用结果。 可以测试多个属性。 可以设置多个属性。 将此视为 Open-AudIT 的 If This,Then That 系统。',
