  '6e26716d17026925c3b8d4c55c7e2fc3093ba3a2844a081285a7cd4f2b463f28' => 'Open-AudIT 具有精细的权限系统，用于确定 Open-AudIT 中的用户可以执行哪些操作以及可以执行哪些操作。 Open-AudIT 可以完全独立，或者使用 Active Directory 或 OpenLDAP 进行身份验证和/或授权。<br><br>Open-AudIT 的管理员完全取决于他们希望基于角色的访问控制如何工作。',
  '6e177920adc8cfab4029a398a3975e2f592b5e14156058080e878958872b7399' => '除此限制外，您可以根据需要自由选择属性。 使用菜单是个好主意',
