  '7a1a3b4d7ce1864333e769ed0c0a5851697fd79ed870b64b8841741f01096794' => '执行子网发现时，如果选择，它首先会在范围或 IP 地址上运行 Nmap ping 扫描。 任何响应的设备都将被端口扫描。 如果未请求 Nmap ping 扫描，则会单独扫描每个 IP 端口。 哪些端口？ 这是由',
  '7a7af84017043f06a7a9dfc27d897619f19274bbda4039c358aa6834e7cd96f3' => '发现扫描选项的属性如下。',
  '7a17d2a7b886ae52a29b4cecce1825149db8096f3d3af42b02154e169abbda06' => '热门 Nmap UDP 端口',
