  '7a89fe84d5f14031c91ace9905a93463548fe8a4f611500e87085f53d6af9ec2' => '位置是可以有与其关联的设备的物理地址。 您可以为其分配坐标，如果已分配设备，则当您拥有 Open-AudIT Enterprise 许可证时，该位置将显示在地图上。',
  '7a96aabbd57bd0c4efd0d2c6e85853905fb85899c8bd241374e26b7b8435300d' => '排除 UDP 端口',
  '7a96c1e67fa3e32370a2bc9b3c8bec94c33484aa61043fb1104758bc1760eddb' => 'Open-AudIT 是由一位讲英语的澳大利亚人编写的。 应用程序中的所有内容均使用英文措辞。 然而，Open-AudIT 始终支持多种语言显示。 这些翻译并不总是正确的，因为开发人员并不是以所提供的每种翻译的语言为母语。<br><br>如果翻译中出现错误，您该怎么办？',
