  '7c3523e506eeb2b325957e2c38d15a319763e1177a06135c23dee33f2d47e65d' => '发现扫描选项只是另一个项目集合。 企业用户可以根据需要创建、读取、更新和删除条目。 专业用户可以阅读所有条目，但不能创建新条目、更新现有条目或删除条目。 社区用户没有允许访问此集合的 GUI。',
  '7c4483cece55839512ff59ae2c600d8deef24e91b31d76b11b2daf1fdaec87c2' => '区',
  '7ca9efd81ee6e590016f942fe45ae11170aee4ab956727d9e2cda70a9aed20ab' => '次要外部提供商',
  '7caa6d4f525de7f4ca1a71c44083d054f5b4678add881936d41daa684edda41c' => '绝密 - 军事/政府分类。 披露将对国家安全造成异常严重的危险。 

秘密 - 军事/政府分类。 泄露会对国家安全造成严重损害。 

机密 - 军事/政府和私营部门分类。 机密数据包括商业秘密、知识数据、应用程序编程代码以及如果发生未经授权的泄露可能严重影响组织的其他数据。 此级别的数据仅可供组织中工作需要所访问数据或与所访问数据直接相关的人员使用。 访问机密数据通常需要每次访问都经过授权。 

私营-私营部门分类。 私有数据包括与人员相关的任何信息，包括仅在组织内部使用的人力资源记录、医疗记录和工资信息。 

敏感 - 军事/政府和私营部门分类。 敏感数据包括组织财务信息，需要采取额外措施来确保其 CIA 和准确性。 披露可能会损害国家安全。 

公共-私营部门分类。 公共数据是一般与公众共享的数据，不会对组织造成负面影响。 公共数据的示例包括组织中有多少人工作以及组织生产或销售哪些产品。 

未分类 - 军事/政府分类。 通常可以向公众发布而不会对国家利益构成任何威胁的任何信息。 

未分配 - 设置之前的默认值。',
