  '8ac501944b9a2ce2d522192d18c2196590b4ef1acddddac9fe7564611b68aad6' => '现在可以检索有关文件或文件目录的详细信息，并根据 Open-AudIT 数据库中的其他属性监视这些文件的更改。 此功能在 Linux Open-AudIT 服务器上开箱即用，但需要更改 Windows Open-AudIT 服务器下的服务帐户名称。 支持的客户端有 Windows 和 Linux。',
  '8ad89738c61b31cee6fefb620e7aa611caa4b3ff83524d2782fc2edb96323299' => '次要文本',
  '8afeb13f9647c3e22488a597556c049e26e09e52e620daed05512c632ecb4151' => '外部IP地址B',
  '8b0332ea1a4c402940406db6b157a285d41a15c686ba72afb9a1610265e8eb50' => '客户端 ID 是 Azure Active Directory 应用程序的 ID。 客户端密钥是您提供给该应用程序的密钥。',
