  '8b3f1358e14b93750be66c086f9b63ea7aefd7cf11491c6ae5110e4f8ff6dae1' => '条形码',
  '8b5d78a6ddc530a48fc90b77395cced8eda3614bdf0f101db2b5667d44e73f2e' => '<p>网络上的设备需要进行管理。 但如何保持记录最新呢？ 电子表格 - 绝对不是。 如果不是几天的话，那在几小时内就会过时。 为什么要手动尝试跟上。 使用 Open-AudIT 自动扫描您的网络并记录您的设备 - 制造商、型号、序列号和 100 多个其他属性。 软件、服务、磁盘、开放端口、用户等的完整列表。自动查看属性是否已添加、删除或更改。<br> <br>一旦设置了 Open-AudIT，您就可以高枕无忧了。 变更报告是否按计划通过电子邮件发送给您，例如 - 本周我们发现了哪些新设备？ 本周安装了哪些新软件？ 上个月有任何硬件更改吗？<br> <br>使用您自己的自定义属性轻松扩展存储的字段。<br> <br>甚至添加未连接到网络的设备或 Open-AudIT 服务器无法访问的设备。<br> <br>网络上的计算机、交换机、路由器、打印机或任何其他设备 - Open-AudIT 都可以审核它们。<br> <br></p>',
  '8b6b57b5ad1d17e61be5ac7a96fb8a6ccb76f3f2050a74582fc419cca6929029' => '物理深度',
  '8b8f3b5f8dcb77ffff82641bfc8ad801651643cd31d706c3df145321b13add25' => '与 <code>software.name</code> 属性匹配的字符串。 您可以使用标准 SQL 通配符百分比 (%) 来匹配一个或多个字符。',
