  '9f8cd49ad14fbc25b259c8ea37e58e827f1bfd8640e3755654231ed9b4d465fe' => '<p>您可以使用任何现有审核脚本的所有选项创建脚本 - 不仅仅是 Windows。 AIX、ESX、Linux、OSX 和 Windows 均涵盖。<br> <br></p>',
