  '9f46eff4942d00b58f8d95425750cbb25f38cf25920daf02932a94fcb61e9a19' => '查询是 Open-AudIT 的重要组成部分。 它们使您能够从您发现的所有设备数据中获取有意义的信息。 与摘要和分组一起，它们提供了提取关键信息的强大机制。',
