  '9fe3e82c3bf18e3bb664d1f204341d163f8bad7998a611cd4080eb33031fa347' => '设备结果',
  '9fe4c68ec20dda7c6b1d3f760e5e6af6b9802897cd59f084b99c68b2ac01574c' => '司机',
  '9fe5c0daf25e6cf462b70adb204c5791af49821597d6e82d07c9d01efa347711' => '随着云功能的引入，您可以提供云、Amazon AWS 或 Microsoft Azure 的详细信息，Open-AudIT 将使用相关 API 检索位置、网络和实例的列表，然后发现每个实例。',
  '9fe5770d03865d42904a242789204b64598e19ac1c5ccdb0989f51eb201ea16d' => '要创建资源，您应该 POST 所需的数据。',
  '9ff64a0c7e21eb6b15b3376c0c6caa571afbaf296b22d940b145e8ad00ad1622' => '附加设备 ID',
  '10adea564ec065113dfb00d49bb1d5061433026cc8e6ee319ffb202d866a72c2' => '许可用户可以根据需要自由添加或修改规则。 如果您的设备的 SNMP OID 与文件中已有的型号不匹配 - 现在您可以轻松添加它。 不再等待我们提供补丁并将其添加到代码库中。<br><br>当您创建规则条目时，您将需要提供名称以及输入和输出列表。 输入和输出作为 JSON 数组存储在数据库中。<br><br>输入具有表和属性、运算符和值。 执行条件时，它的工作方式如下： If $table 。 $attribute $operator $value 然后应用输出。<br><br>下面是匹配 SNMP OID 并设置模型的示例规则。<br>',
