  '11c9caccba89b1a853ed9a014bdb2d0b95b670ef821a3b3fb96df670ad78f92e' => '警告 - 使用软件策略创建基线时，目前 Centos 和 RedHat 使用名称 <i>kernel</i> 和 <i>kernel-devel</i> 打包内核。 可以同时安装多个同名且不同版本的软件包。 基于 Debian 的发行版使用诸如 <i>linux-image-3.13.0-24-generic</i> 之类的名称，请注意版本号包含在软件包名称中。 由于基于 RedHat 的操作系统使用此格式，并且随后具有多个具有不同版本的相同软件包名称，因此我们目前从软件策略中排除 <i>kernel</i> 和 <i>kernel-devel</i>。 这可能会在未来的更新中得到解决。',
