  '63f56a41d24005aa0624a7be907853327e78c8509a38c71437a9ea2df591bf51' => 'Open-AudIT 在其发现功能中使用 Nmap。如果没有 Nmap，Open-AudIT 将无法正常运行。每个 Open-AudIT 安装都假定已安装 Nmap，并且还将在 Discovery 网页上对其进行测试。有关 Open-AudIT 和 Nmap 的更多信息，请参见此处',
