  '66a9911b60421107c034008437af9e89aa11906e304272244ad40cb609ce1016' => '最近有人问我们这个问题 - 您认为 Open-AudIT 比其他类似程序更安全吗？与大多数事情一样，答案是<i>这取决于</i>。<br><br>Open-AudIT 可以以极其安全的方式进行操作。但与基于计算机的安全性一样，您希望制作的东西越安全，使用起来就越不方便。我想起了古老的短语<i>最安全的计算机是关闭并放在柜子里的计算机<i>。<br><br>下面我们将概述一些可与 Open-AudIT 一起使用的选项，以提高安全性。与 Open-AudIT 中的大多数项目一样，这些是选项，而不是强制性的。您采取何种安全措施取决于您。',
