  '434d224d019107a70c630ec7692c386128143f5af7e9ffa4dacd9e1a6d65b041' => '远程地址',
  '436fe71bb9561f0596161c4d50c7b23327b4189acaf63dc89f4f9205b67a7528' => '通过',
  '437e086ba91775408359d1c0b1f8d86b352bf12d47ed030435c224b93bc5db4e' => 'Open-AudIT 中使用的 SQL 查询需要使用反引号 - ` 字符，而不是字段的标准单引号。 在大多数美国 Windows 键盘上，反引号键与波形符 ~ 一起位于键盘的左上角。 在美国 Mac 键盘上，反引号键位于 SHIFT 键旁边。 标准单引号仍然用于括起值，如下例所示。',
  '439d70b4838cd8c480e911f1d4c1eab4748e0035cf5003c7c4815c2acb94f0ac' => '选择外部计数',
  '440c92e36321cb206b6e8b378cac2834fe21b56a118fefba0b6b2ae48f7c7e35' => 'Open-AudIT 如何以及为何更加安全',
  '442aded87a55aa8c8f7d5ff0c30228150d4b1cb8756e4be138d615ca4708fc26' => '表现',
  '442b7bd40f7fec79582ba347b1db480023dcd5147c5a3429275dbd4976d912f4' => '单击删除按钮从 Open-AudIT 中删除示例设备。<br>这将从数据库中删除以下设备。',
  '450e0b4c4397e1fe98fa65aa10711734b4e966a657ada1808d166a652fb354d8' => '排除 TCP 端口',
  '450f17d1ba65477d5b8185d6624f6b10505cc83c36099472822306e2ba7be7a5' => '要创建新条目，请单击右上角的“创建”按钮。',
  '455ab57f64f73edd2b2fa769aabb72c98186e9e2a8396a63d7f340341c451fc9' => '文件导入',
  '464c4ffd019e1e9691dcf0537c797353ef2b1c1d4833d3d463e5b74ae4547344' => '编辑',
  '470f335e24102878f3922ef9a6de56ecc6d7b496444d54152ebcb900cd528879' => '已在 LDAP 中搜索该用户，但未找到其帐户。 检查 LDAP 服务器日志。 用户凭据已起作用，但未找到该用户。 另请检查您在 Open-AudIT 中创建 LDAP 服务器时是否指定了正确的基本 DN 属性。',
  '471f6f47bbd70ad73ac4e84c33768801c5335889810bbc570b13387de626806b' => '主题密钥标识',
  '478b13e323f01283ec30ab8196a03da408ad75be80d6b1c9ee3f9151f30bfa22' => '子网发现',
  '489eb737ed24529f35d104e46e491685f5da859566d33d0641fa0511a3d87d41' => '操作系统许可证类型',
  '491b795f44e2a7eaca1a772d619c487929fed43468f2dc3789955326be1cca09' => '<p><strong>基线</strong> - 包含基线定义和各个策略测试的总体文档。<br> <br> <strong>策略</strong> - 基线中包含的各个测试。 每个测试都是针对一个特定项目。 一个例子是测试 SSH 版本 1.2.3。<br> <br> <strong>详细信息</strong> - 基线可以比较 netstat 端口、用户和软件。<br> <br> <strong>软件</strong> - 为了比较软件，我们检查名称和版本。 由于版本号的格式并不全部标准化，因此当我们收到审核结果时，我们会创建一个名为 software_plated 的新属性，该属性与每个包的其余软件详细信息一起存储在数据库中。 因此，使用软件策略的基线在（至少）未经 1.10 审核的设备上运行时将不起作用。 软件策略可以针对版本“等于”、“大于”或“等于或大于”进行测试。<br> <br> <strong>Netstat 端口</strong> - Netstat 端口使用端口号、协议和程序的组合。 如果全部都存在，则策略通过。<br> <br> <strong>用户</strong> - 用户的工作方式与 Netstat 端口类似。 如果用户存在且具有匹配的名称、状态和密码详细信息（可更改、过期、必需），则策略通过。<br> <br> </p>',
  '491dc54ecc8d31d616f6b885c73c648d78e220d64add25246c6f28d4b4d984ad' => '匹配字符串',
  '501fb0997aa6c7546f10968b26ec727e3acf478ca3a25d57a37ea25b4ab0640b' => '表明本网站所需的服务级别。',
