  '6971fd747e91de24d7afbfceeb6c74f31b0f8fb831e16f8d30b8e984a73256a7' => '要使用此企业功能，您首先需要像往常一样在 Open-AudIT 中创建用户。 无需指定密码。 您必须分配角色和组织。 Open-AudIT 中的用户名应与 OKTA <i>name</i> 属性匹配。 不需要全名或电子邮件 - 这些将从 OKTA 填充。 如果您不知道您的用户<i>名称<i>，请不要担心。 您可以在 Open-AudIT 中创建新的身份验证方法，并在 OKTA 中创建应用程序，当用户尝试在没有预先存在的用户的情况下登录 Open-AudIT 时，请检查日志，您将看到记录了他们的<i>名称<i>，以方便您使用。<br></p><p>然后，通过转到菜单 -> 管理 -> 身份验证方法 -> 创建身份验证，在 Open-AudIT 中创建新的身份验证方法。 提供名称并将<i>类型</i>设置为 Okta。',
