  '76318525ca68d5dd1d1ad3456ebcba6b13ba9c99a9983e08e6444ec81e86fade' => '当使用 Web 浏览器但您希望查看 JSON 格式的结果时，使用格式选项非常有用。 添加 format=json 可以实现这一点。 通常，Web 浏览器会将其接受标头设置为 HTML，因此在这种情况下，我们返回渲染的页面。 使用 API 检索 JSON，您应该将接受标头设置为',
