  '133001949a45cced739934ce873925ba218b8e7d424922a99479f55fdf08acdc' => 'Open-AudIT 附带了 admin、org_admin 和 user 的内置角色。<br><br>通常，作为 Open-AudIT 应用程序本身的管理员的用户应该具有 admin 和可能的 org_admin 角色。<br><br>一个用户可以拥有多个角色。 该权限将在最许可级别应用 - IE，如果用户具有 user 和 org_admin 角色，他们将能够创建位置，因为 org_admin 授予此权限，即使用户角色没有。<br><br>admin 角色允许访问配置、数据库、组、ldap 服务器、日志、查询和角色等集合。 影响整个应用程序的全局项目。<br><br>org_admin 角色通常允许对包含 org_id 列的任何集合创建、读取、更新和删除操作。 实际上，除了上述某些集合之外的所有数据都将包含 <code>org_id</code> 列。<br><br>用户角色通常允许对具有 org_id 列的所有项目进行只读访问。',
