  '321909804606dd70fefc6f848521695247fe86d2e819597faf042b9bca49dffd' => '使用服务版本检测。 当检测到的端口被检测为开放时，如果设置为<i>y</i>，Nmap将查询目标设备，试图确定该端口上运行的服务的版本。<br>这在识别未分类设备时非常有用。 这是以前没有使用过的。',
  '339511427159e7ac735031ac155ed425acd92c714511beff10d38ed6104ecefc' => '模块索引',
  '597043655349dcb6f5051a54921953b5d7f56a126ce3d1d809312e26e05406e8' => '有时无代理发现并不适合您的用例。 也许您的电脑有严格的防火墙。 当您安排发现时，它们可能不在网络上。 也许它们是由远程工作人员使用的。 无论如何，这都是代理人可以提供帮助的地方。 将其安装在目标计算机上，它将按计划<i>签入</i>您的 Open-AudIT 服务器并接受任务。 服务器请求的最常见任务是代理自行审核并发送结果。',
  '722535823343cbaa050d74e0770007cd235ecb07db1af8d4ba7cb0aa87a5cdd4' => '密码已禁用',
  '762655660249c474ff1834597320759cb4b07de73bf32ac2f75fb00ec491cc6a' => '<p>SQL 的 SELECT 部分<em>必须</em>仅包含 <code>DISTINCT(devices.id)</code>。<br> <br>SQL 的 WHERE 部分<em>必须</em>包含 <code>WHERE @filter</code>，以便 Open-AudIT 知道将查询限制到适当的组织。 不包含此条件的 SQL 将导致组创建失败。<br> <br>SQL 选择运行 Debian 操作系统的所有设备的示例 - <code>SELECT DISTINCT(devices.id) FROM devices WHERE @filter AND devices.os_family = "Debian"</code><br> <br></p>',
