  'b54a278a9f86c2c81b50629775866475691da0aacc1b6e345980e3bfec851341' => '<p>SQL 的 SELECT 部分<em>必须</em>包含完全限定的列。 IE - <code>SELECT devices.id AS `devices.id`, devices.name AS `devices.name` ...</code>。<br> <br>SQL 的 WHERE 部分<em>必须</em>包含 <code>WHERE @filter</code>，以便 Open-AudIT 知道将查询限制到适当的组织。 不包含此条件的 SQL 将导致创建查询失败，除非您具有管理员角色。<br> <br>示例查询 SQL 显示 <code>os_group</code> 属性为“Linux”的设备上的属性 - <br><code>SELECT devices.id AS `devices.id`, devices.icon AS `devices.icon`, devices.type AS `devices.type`, devices.name AS `devices.name`, devices.os_name AS `devices.os_name` 来自设备，其中@filter AND devices.os_group = "Linux"</code><br> <br></p>',
