  'b99d0836f3aa0ad0b6d964c0eafeb81d6c9936685c2e0c476c554124fb822a09' => '如果满足以下条件：<br><ul><li>某个角色拥有指定的 ad_group</li><li>某个组织拥有指定的 ad_group</li><li>LDAP 服务器已将 use_roles 设置为 y</li><li>用户存在于 LDAP（无论是 Active Directory 还是 OpenLDAP）中并且位于指定的 ad_group 中</li></ul>该用户无需在 Open-AudIT 中拥有帐户即可登录 Open-AudIT 被创建。 Open-AudIT 将查询相关 LDAP，如果用户位于所需组中但不在 Open-AudIT 中，则 Open-AudIT 中的用户属性（姓名、全名、电子邮件、角色、组织等）将自动填充，并且他们将登录。<br> <br>',
