  'bc45ff1a1dfba1e8bd80b64fe3c521b2178b11c8e381071fed63bdf4bb81a0fb' => '该属性是使用attributes.devices.sensitivity 填充的。 要添加另一个条目，请添加到属性列表。 

绝密 - 军事/政府分类。 披露将对国家安全造成异常严重的危险。 

秘密 - 军事/政府分类。 泄露会对国家安全造成严重损害。 

机密 - 军事/政府和私营部门分类。 机密数据包括商业秘密、知识数据、应用程序编程代码以及如果发生未经授权的泄露可能严重影响组织的其他数据。 此级别的数据仅可供组织中工作需要所访问数据或与所访问数据直接相关的人员使用。 访问机密数据通常需要每次访问都经过授权。 

私营-私营部门分类。 私有数据包括与人员相关的任何信息，包括仅在组织内部使用的人力资源记录、医疗记录和工资信息。 

敏感 - 军事/政府和私营部门分类。 敏感数据包括组织财务信息，需要采取额外措施来确保其 CIA 和准确性。 披露可能会损害国家安全。 

公共-私营部门分类。 公共数据是一般与公众共享的数据，不会对组织造成负面影响。 公共数据的示例包括组织中有多少人工作以及组织生产或销售哪些产品。 

未分类 - 军事/政府分类。 通常可以向公众发布而不会对国家利益构成任何威胁的任何信息。 

未分配 - 设置之前的默认值。',
