  'bd8d1850c8b79259b8aa75bfd676dc7e17e8e48254d3e49fb9caf431bf698aa3' => '<p>能够确定哪些机器配置相同是系统管理和审核的主要部分 – 现在，相关报告将变得简单且自动化。 一旦定义了基线，它将自动按照预定的时间表针对一组设备运行。 这些执行基线的输出可用于 Web 查看、导入第三方系统甚至作为打印报告。<br> <br>基线使您能够将审核数据与先前定义的一组属性（您的基线）相结合，以确定设备的合规性。<br> <br>例如，您可以从运行 Centos 6 的设备创建基线，该设备充当集群中的 apache 服务器之一。 您知道该特定服务器的配置方式正是您想要的，但您不确定集群中的其他服务器的配置是否完全相同。 基线使您能够确定这一点。<br> <br> </p>',
