  'cb6e50f40bdf26ac40c7ec38619668078b8649a00a01afba89ae2a6f96bceee8' => '<p>任务有一个反映 unix cron 计划的计划。 分钟、小时、月日、月、周日的属性均按照 cron 定义进行操作。 您可以使用逗号分隔值（无空格）选择多个。 您可以使用 * 选择每个值。<br> <br>任务的<code>类型</code>可以是以下之一：基线、收集器、发现、查询、报告或摘要。<br> <br>如果您希望计划基线或发现，则需要在创建任务之前创建这些值。 您必须在 <code>sub_resource_id</code> 中使用项目类型的 ID。 例如，如果您希望安排发现，请在 <code>sub_resource_id</code> 中使用特定的发现 ID。<br> <br><code>uuid</code> 的值特定于每个 Open-AudIT 服务器。 您可以在配置中找到您的唯一值。<br> <br><code>options</code> 属性是一个 JSON 文档，其中包含运行任务所需的任何额外属性。 报告、查询和摘要的额外属性为：<code>email_address</code> 和 <code>format</code>。 基线的额外属性是 <code>group_id</code>。<br> <br></p>',
  'cb96bb2127aad27a7b2b5b99ca34ff636d00af10ea3b432b02dcc26d4b4697ee' => '如何利用漏洞（例如，网络、相邻、本地、物理）。',
