  'ccfe8110594c976634313edab218370622b3145c4b5cd6afd8eaffb09f30f24a' => '该角色没有指定 AD 组。 检查 Open-AudIT 中的角色详细信息。',
  'cd0a86c2bf2d97fb46ad4cd82f0b19ce971af5d603ca3126b680729c39c86ba6' => '<p>Open-AudIT 提供开箱即用的多租户！<br> <br>Open-AudIT 中的组织（组织）是一个关键项目。 用户拥有一个主要组织以及他们可以访问的组织列表。 用户将其与分配的“角色”列表结合起来，这些“角色”定义了他们可以对分配给他们有权访问的组织的项目执行哪些操作。 用户“组织”和“角色”的组合定义了他们在 Open-AudIT 中可以做什么和不能做什么。<br> <br>Open-AudIT 中的大多数项目都分配给组织。 设备、位置、网络等<br><br>组织可以有子组织。 想像一个组织图（树）结构。 如果用户有权访问特定组织，他们也有权访问该组织的后代。 有关详细信息，请参阅此<a href="/index.php/faq?name=用户、角色和组织">常见问题解答</a>。</p>',
  'cd19f16ce3685ab7e3a057b8e590d43c159afa0f60d689b52f010fd30191d14e' => '它可以是 varchar（文本字段）、列表（可选择的值列表）或日期。',
