  'ce770e2c925fae0721bbf70b4a7905adc1edaa29c30e4704f2ba2d5d9d79dbc7' => '要么没有，要么存在。 

<strong>无</strong> - 成功的攻击不依赖于易受攻击系统的部署和执行条件。 攻击者预计能够到达该漏洞并在该漏洞的所有或大多数实例下执行漏洞利用。 

<strong>存在</strong> - 成功的攻击取决于启用攻击的易受攻击的系统的特定部署和执行条件的存在。 这些包括：

 必须赢得竞争条件才能成功利用该漏洞。 攻击的成功取决于不受攻击者完全控制的执行条件。 攻击可能需要针对单个目标多次发起才能成功。 

网络注入。 攻击者必须将自己注入目标和受害者请求的资源之间的逻辑网络路径（例如，需要路径攻击者的漏洞）。',
  'ce778f2b34ed139cb7c709cb62a209e17e8118bb8991eaca37d138b5bc5aaeeb' => '法律要求',
  'ce108352268bc1ab7945c555434c0d7c9369e7e48feb82999a8f7c83dd4bf9e2' => '<p>Open-AudIT 中的角色是一个关键项目。 用户拥有一个主要组织以及他们可以访问的组织列表。 用户将其与分配的角色列表结合起来，这些角色定义了他们可以对分配给他们有权访问的组织的项目执行哪些操作。 用户“组织”和“角色”的组合定义了他们在 Open-AudIT 中可以做什么和不能做什么。<br> <br>
 获得完整的 Open-AudIT Enterprise 体验。 创建角色可以对用户在 Open-AudIT 中可以执行的操作进行细粒度控制。<br> <br>
 授权的主要方法（用户可以执行的操作）基于用户角色。 默认角色定义为 admin、org_admin、reporter 和 user。 每个角色对每个端点都有一组权限（创建、读取、更新、删除）。 Open-AudIT Enterprise 中启用了定义其他角色和编辑现有角色的功能。<br> <br>角色还可以与 LDAP（Active Directory 和 OpenLDAP）授权一起使用。 企业许可安装能够为每个定义的角色自定义 LDAP 组。<br> <br></p>',
