  'e02415ca970ae099f2f05820589a42cda50167e580ae6a327267309725ff2b75' => '用户拥有一个主要组织以及他们可以访问的组织列表。用户将其与分配的角色列表结合起来，这些角色定义了他们可以对分配给他们有权访问的组织的项目执行哪些操作。用户<i>组织</i>和<i>角色</i>的组合定义了他们在Open-AudIT中可以做什么和不能做什么。',
  'e02591fb187e94127488f5d84c15862801ad1dc5ed8cf9ae8f7dcfda292d7f74' => '用于通过电子邮件发送的输出的格式。',
