  'e1d87f66a9e33310a7a9d7544d478cc67fd9ccdac315830b392298b89c9d7078' => '需要 API 密钥。',
  'e1e6b54cb2652602a6a838bed90b79b977b64b49e5876a06c40f9dc461d88ce5' => '<p>Open-AudIT 提供开箱即用的多租户！<br> <br>Open-AudIT 中的组织（组织）是一个关键项目。用户拥有一个主要组织以及他们可以访问的组织列表。用户将其与分配的“角色”列表结合起来，这些“角色”定义了他们可以对分配给他们有权访问的组织的项目执行哪些操作。用户“组织”和“角色”的组合定义了他们在 Open-AudIT 中可以做什么和不能做什么。<br> <br>Open-AudIT 中的大多数项目都分配给组织。设备、位置、网络等<br><br>组织可以有子组织。想像一个组织图（树）结构。如果用户有权访问特定组织，他们也有权访问该组织的后代。</p>',
  'e1fdd686df0189f8828937561510b5fa2262a77aa5f8030647ed1a0db9e7be41' => '地点区。',
