  'e4d2d8f90a842e6c8d550a0e90c1049cbe2569968ccad6dedfe4476bc4b63a33' => '行数',
  'e4ea20ef135a6dc990cb3e18d29ae630e7674598e5e8d44e8f32c6e67b69daf7' => '当 Nmap 无法确定端口是开放还是已过滤时，会将端口置于此状态。对于开放端口没有响应的扫描类型，会发生这种情况。缺乏响应还可能意味着数据包过滤器丢弃了探测或其引起的任何响应。所以Nmap不能确定端口是开放的还是被过滤的。 UDP、IP 协议、FIN、NULL 和 Xmas 扫描以这种方式对端口进行分类。',
  'e4fe446b362d2b75000dc5888dbeb9028420d4eea1aa62e0489dcb5fa6658efa' => '现在，对于订阅 ID，单击“所有服务”、“订阅”并复制它。',
  'e5b53649f73ad9c217b10b587a3fff969429d3634a4eb97d4ba07b55bc444de1' => '检索租户 ID。打开 Azure 门户，单击 Azure Active Directory、属性，租户 ID 将显示为您的目录 ID - 不要因为名称不匹配而责怪我，这就是 Microsoft 的做法。',
  'e5c7fd58c408708dd741da76f6e33e95a4bd071efc8560789a2b23e2eb945979' => '内核版本',
  'e5c9d7030bada2fe792ad7e4a26ca44379a73f3fe16805ac1359e46759a1571a' => '测试',
  'e5d12ab5f3267be1d85a78fd2f03a5c5b45b2c8470092fb31d91f008f697aff3' => '注意 - 您可以通过创建注册表项来审核远程计算机，而无需使用实际的管理员帐户。在每台要审核的计算机上创建以下密钥，并确保使用的用户凭据是管理员组的成员。',
  'e5e049febc4fa2e5375a64da9039847cf5375407eb9976d3a002804e0198e8de' => '该云中处于运行状态的设备数量。链接到 <code>devices.cloud_id</code> 和 <code>devices.instance_state</code>。',
