  'e31d4ed8333c6b76dbfa8c0f41a6adb12a9df291731d577530028160d29a01bb' => '<p>有效子网属性的一些示例包括：192.168.1.1（单个 IP 地址）、192.168.1.0/24（子网）、192.168.1-3.1-20（一系列 IP 地址）。<br> <br><em>注意</em> - 创建<strong>种子</strong>发现时，仅有效子网可以使用（192.168.1.0/24）。范围 (192.168.1.10-20) 无法限制已发现的 IP。 <br> <br><em>注意</em> - 只有子网（如示例 - 192.168.1.0/24）才能自动为 Open-AudIT 创建有效网络。 <br> <br>如果您使用 Active Directory 类型，请确保您拥有适当的凭据来与<a href="../credentials">凭据</a>中已有的域控制器通信。<br> <br></p>',
  'e34dd616b94ba2545547b9ca26b9b2847593d7161c17245634c155e390208b1f' => '黎巴嫩',
  'e37d1541c8256d701d83eb521418100abf53be4dc3396ab112aaadd5d0df15fe' => '打印机端口名称',
  'e39c65e2434ad0154bc296eab85a1a5796669ec9510ace31f79771eb13674876' => '用户政策',
  'e40ffd47eb2dbd811d57ecd953a20c28f1fce6d393a5f95c7e20068addba0ba3' => 'Open-AudIT 中的漏洞项目本质上可以被视为对数据库的查询，以确定您对给定 CVE 报告的潜在暴露程度。漏洞由 CVE 报告以及来自 FirstWave 的丰富数据组成。这两个项目组合起来生成一个合适的查询，该查询会自动从 FirstWave 下载。',
  'e44ee7121ae25b62c6daf9a1fd5886d1a372f30145aa61e38bd6aea0e2f4df3c' => '等待其完成，然后粘贴下一行以安装代理。',
  'e46af612059a3ea57d2ae761a9d365817335bc86358e3d1da4b38254160eeaa5' => '用于查看特定表及其列的项目。这将使您能够准确地找到您需要的内容，而不是通过架构创建脚本的 MySQL 控制台进行搜索。',
  'e47a2667bfb6fee30a3daf519bd126d34e2c761c2282cd686269f752383fd81f' => '偏移量是您希望从中返回数据的设备的数量。',
  'e48ade009c1dda5d3b871c32397ca511dfee2fe361a3156885a758ad3166799d' => '内核版本',
  'e49c2dc561765487f57d6c10ade7dbcb3bfba6194748ccf2afaab5fffb4db9de' => '具有 devices::update 权限。',
  'e52f6e6cc40b423d7f85f8d22b7c0681e77f695d222939703f13fca9d6076d03' => '您可以通过转到菜单 -> 管理 -> 收集器 -> 将此安装设置为收集器，将任何服务器变成收集器。您将需要凭据才能登录此安装将向其报告的服务器。',
  'e56d6b4860acd0e805d076d819144c8bf53f52d3aa7c24a9ba70b62e3622ef20' => '发射概况',
