  'eabea6c036ac2f216944a2ae0798d33acb974c715a1cabe443d74b63a65ba786' => '当 Open-AudIT 通过在审核运行期间发现设备或通过用户导入设备来接收有关设备的数据时，它必须确定此发现的设备是否与其数据库中已存在的设备匹配，或者是否是应添加的新设备。 Open-AudIT 使用一系列 12 个属性匹配来确定这一点。匹配规则作为 OR 比较，而不是 AND。这意味着将发现的设备中的字段与 dB 中的字段相匹配的第一条规则将解析为现有设备。所有匹配规则都必须失败才能使设备成为新设备并导致创建新记录。',
