  'ed609267907c8892c815b710cba45d63f85d8403d3e29d42ea26d5ccb4a1d995' => '<p>借助 Open-AudIT Professional 和 Enterprise，您可以自动化并安排发现、报告生成或基线检查，以便在您需要时、根据您需要的频率运行。安排您的发现每晚运行，并生成报告并每天早上通过电子邮件发送给关键人员。复杂或简单的计划、设备发现和报告生成只需单击一下即可。<br> <br>为每个子网或 AD 控制器创建单独的发现计划，添加为目标受众创建的报告。制定简单或复杂的计划来支持公司需求，避免备份或影响运营，或者只是为了分散负载并加快审计完成速度。<br> <br></p>',
