  'f00b239f4d3261ffe2bd12bccf2d374555b3113c4c89cd1c2e8dd5eedc158ca9' => '<p>如果您选择列表类型，则将启用“值”字段。您应该在此处放置一个逗号分隔的可选值列表。每当编辑字段时，这些属性都会显示在下拉框中。<br> <br>与大多数其他属性一样，可以批量编辑字段。像平常一样使用批量编辑功能，您将看到字段可供输入。<br> <br>查看设备详细信息屏幕，打开包含该字段的部分，然后（如果您有足够的访问权限）您可以单击字段值进行编辑。<br> <br></p>',
