  'f3fc8f62cbfc3371a045edecd12f7c8d5ae36958437ce6c8e8cd7ea23c1e8dec' => '<p>凭据在存储在数据库中时会被加密。<br> <br>运行发现时，设备会首先检索其凭据并测试连接（从<code>凭据</code>表中）。如果这些失败，则还会针对设备测试与给定 Org <code>credentials.org_id</code> 关联的凭据。工作凭证存储在凭证表中的单个设备级别（注意 - 表名称中没有“s”）。<br> <br>SSH 密钥在 SSH 用户名/密码之前进行测试。测试 SSH 时，凭据还将被标记为使用 sudo 或 root。<br> <br>为了便于使用，Windows 密码不应包含单引号或双引号。这是远程 WMI 限制，而不是 Open-AudIT 限制。<br> <br></p>',
