  'f579cdca4ce2504a114acfa8c231aaec5fee8bb11ddf3987d3311945ee9b2c50' => '当您在其中一个列标题中输入文本时，您可以简单地使用普通单词。例如，当您在<i>类型</i>列上方的搜索框中输入<code>计算机</code>时，搜索将返回类型为“计算机”的所有设备。本质上，Open-AudIT 使用类似 <code>devices?devices.type=computer</code> 的 URL 请求数据。现在，使用 dataTables 搜索与标准搜索相比，存在一个显着差异',
